                <li><strong>बुलेट काउंट मिलाएं:</strong> बुलेट्स-प्रति-स्लाइड सेलेक्टर को उस अनुसार सेट करें कि आप टेक्स्ट को कैसे विभाजित करना चाहते हैं। AI बिना पुनर्लेखन के क्रमिक रूप से चंक करेगा और यदि आवश्यक हो तो खाली आइटम पैड करेगा।</li>
