                <li><strong>Send workflow</strong> — Send चयनित स्लाइड काउंट और सहेजी गई स्रोत टेक्स्ट का उपयोग करके उपयोगकर्ता प्रॉम्प्ट को स्वचालित रूप से बनाता है।</li>
